exarion_map 1
# Carte ecrite ENTIEREMENT A LA MAIN, sans passer par map_save.
#
# C'est la seule preuve qui compte pour justifier un format texte : si
# personne ne peut ecrire une carte dans un editeur, autant faire du binaire.
#
# box    centre(x y z)  taille(x y z)  couleur(r v b, LINEAIRE)

name essai a la main
spawn 0 1 12  0 -8

# --- une piece de 24 x 24, ouverte sur le ciel ---
box   0 -0.5   0    24  1 24    0.3  0.31 0.34
box -12.3 3    0     0.6 7 24   0.48 0.49 0.52
box  12.3 3    0     0.6 7 24   0.48 0.49 0.52
box   0   3  -12.3  24   7  0.6 0.48 0.49 0.52
box   0   3   12.3  24   7  0.6 0.48 0.49 0.52

# --- deux marches et une estrade, pour verifier le franchissement ---
box  0 0.15 -3    6 0.3 1.2   0.55 0.48 0.38
box  0 0.45 -4.2  6 0.9 1.2   0.55 0.48 0.38
box  0 0.9  -7    8 1.8 4     0.42 0.5  0.58

# --- deux piliers, pour ecouter l'occlusion du son en tournant autour ---
box -5 3 2   1.2 7 1.2   0.6 0.4 0.38
box  5 3 2   1.2 7 1.2   0.6 0.4 0.38

# --- eclairage : un soleil et deux lampes ---
light_dir   -0.35 -0.85 -0.4   0.62 0.7 0.85   1.1
light_point -6 5 -6   1 0.78 0.48   140  22
light_point  6 5  6   1 0.78 0.48   140  22
light_spot   0 6 -7   0 -1 0   0.55 0.75 1   280  16  20 34
